fn flip(a: &mut Vec<i32>, num: usize) {
    let mut left = 0;
    let mut right = num;

    while left < right {
        // Swap the elements at the left and right indices
        a.swap(left, right);
        left += 1;
        right -= 1;
    }
}

fn main() {
    let mut arr = vec![1, 2, 3, 4, 5];
    let index = 3;
    flip(&mut arr, index);
    println!("{:?}", arr); // Output should be [4, 3, 2, 1, 5]
}